import {
  getEditorProfile,
} from "../../profiles";

export interface PathSuggestion {
  path: string;
  title: string | null;
}

/*
 * field-paths.json (generated by scripts/generate_editor_schemas.py)
 * marks every array segment with a literal "[]" — it only records
 * an array's element shape once, not per index — turned into a
 * concrete ".0." here since that's what setPath()/
 * applyTemplateFields() need to actually address a value. Every
 * suggestion defaults array indices to 0; editing that digit for a
 * different array position is left to the user.
 */
function toConcretePath(
  path: string,
): string {
  return path.replace(/\[]/g, ".0");
}

/**
 * Ranks exact-prefix matches first, then any other substring match
 * on the path or title, capped at `limit` so a broad query (e.g. a
 * single common letter) doesn't dump the whole catalog into the
 * dropdown. Reads the active profile's own field catalog — a path
 * suggestion is only meaningful relative to the schema the record
 * currently being edited actually uses.
 */
export function suggestPaths(
  profileId: string,
  query: string,
  limit = 20,
): PathSuggestion[] {
  const profile = getEditorProfile(profileId);

  const catalog: PathSuggestion[] = profile.fieldPaths.map(
    (field) => ({
      path: toConcretePath(field.path),
      title: field.title,
    }),
  );

  const term = query.trim().toLowerCase();

  if (!term) {
    return [];
  }

  const startsWith: PathSuggestion[] = [];
  const contains: PathSuggestion[] = [];

  for (const entry of catalog) {
    if (entry.path.toLowerCase().startsWith(term)) {
      startsWith.push(entry);
    } else if (
      entry.path.toLowerCase().includes(term)
      || entry.title?.toLowerCase().includes(term)
    ) {
      contains.push(entry);
    }
  }

  return [...startsWith, ...contains].slice(0, limit);
}
